CREATE COLUMN TABLE "TEST_AP"."OBSL" ("AbsEntry" INTEGER CS_INT NOT NULL , "FldAbs" INTEGER CS_INT NOT NULL , "SLCode" NVARCHAR(50) NOT NULL , "Descr" NVARCHAR(50), "UserSign" SMALLINT CS_INT, "DataSource" NVARCHAR(1) DEFAULT 'N', "Transfered" NVARCHAR(1) DEFAULT 'N', "Instance" SMALLINT CS_INT DEFAULT 0, "LogInstanc" INTEGER CS_INT DEFAULT 0, "CreateDate" LONGDATE CS_LONGDATE, "UserSign2" SMALLINT CS_INT, "UpdateDate" LONGDATE CS_LONGDATE, "Deleted" NVARCHAR(1) DEFAULT 'N', PRIMARY KEY ("AbsEntry")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "OBSL_BUSINESS_K" ON "TEST_AP"."OBSL" ( "FldAbs" ASC, "SLCode" ASC )